export function parseWrapperSellYtInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedWrapperSellYtInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 20) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 20,
    });
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      seller: getNextAccount(),
      market: getNextAccount(),
      tokenSyTrader: getNextAccount(),
      tokenYtTrader: getNextAccount(),
      tokenPtTrader: getNextAccount(),
      tokenSyEscrow: getNextAccount(),
      tokenPtEscrow: getNextAccount(),
      marketAddressLookupTable: getNextAccount(),
      tokenProgram: getNextAccount(),
      syProgram: getNextAccount(),
      vaultAuthority: getNextAccount(),
      vault: getNextAccount(),
      tokenSyEscrowVault: getNextAccount(),
      mintYt: getNextAccount(),
      mintPt: getNextAccount(),
      vaultAddressLookupTable: getNextAccount(),
      yieldPosition: getNextAccount(),
      tokenFeeTreasurySy: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getWrapperSellYtInstructionDataDecoder().decode(instruction.data),
  };
}
